    def dvc_cmd(self) -> str:
        cmd = f"{self.xenv_cmd} quarto render {self.target_path}"
        if self.to is not None:
            cmd += f" --to {self.to}"
        for arg in self.args:
            cmd += f" {quote_arg(arg)}"
        return cmd.strip()

    @property

